git-attic # Source: https://github.com/maximeh/dotfiles/blob/master/common/.bin/git-attic
#!/bin/sh # git-attic [-M] [PATH] - list deleted files of Git repositories # # Use -M to not show renamed files, and other git-log options as you like. git log --raw --no-renames --date=short --format=&#34;%h %cd&#34; &#34;$@&#34; | awk &#39;/^[0-9a-f]/ { commit=$1; date=$2 } /^:/ &amp;&amp; $5 == &#34;D&#34; { print date, commit &#34;^:&#34; $6 }&#39; | less Example # ➜ kubernetes-the-hard-way git:(master) ✗ git log --raw --no-renames --date=short --format=&#34;%h %cd&#34; &#34;$@&#34; | awk &#39;/^[0-9a-f]/ { commit=$1; date=$2 } /^:/ &amp;&amp; $5 == &#34;D&#34; { print date, commit &#34;^:&#34; $6 }&#39; 2019-11-20 374e8d9^:docs/using-rst/pdp-template-rst.rst 2019-11-17 7911114^:src/certificates/admin-csr.json 2019-11-17 7911114^:src/certificates/admin-key.pem 2019-11-17 7911114^:src/certificates/admin.csr 2019-11-17 7911114^:src/certificates/admin.pem 2019-11-17 7911114^:src/certificates/ca-config.json 2019-11-17 7911114^:src/certificates/ca-csr.json 2019-11-17 7911114^:src/certificates/ca-key.pem 2019-11-17 7911114^:src/certificates/ca.csr 2019-11-17 7911114^:src/certificates/ca.pem 2019-11-17 7911114^:src/certificates/copy-certificates-to-servers.sh git trail # I cannot remember where is this one from :-(
#!/bin/sh -e # git trail [-r] [-t] [COMMIT] - show all branching points in Git history [ &#34;$1&#34; = -r ] &amp;&amp; shift || REMOTES=&#34;-e refs/remotes/&#34; [ &#34;$1&#34; = -t ] &amp;&amp; shift || TAGS=&#34;-e refs/tags/&#34; COMMIT=$(git rev-parse --no-flags --default HEAD &#34;$@&#34;) { git for-each-ref | grep -v -e &#39;^$&#39; $TAGS $REMOTES git log --date=short --format=&#34;%cd %h %H&#34; &#34;$@&#34; } | awk &#39; $2 == &#34;commit&#34; || $2 == &#34;tag&#34; { &#34;git merge-base &#39;$COMMIT&#39; &#34; $1 | getline mb merge[mb] = merge[mb] &#34; &#34; $3 } { if ($3 in merge) { split(merge[$3], mbs, &#34; &#34;) for (i in mbs) { &#34;git name-rev --name-only --refs=\&#34;&#34; mbs[i] &#34;\&#34; &#34; $3 | getline nr if (nr != &#34;undefined&#34;) print $1, $2, nr # skip unreachable commits } }

